DROP TABLE IF EXISTS `dispatch_suggestions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `dispatch_suggestions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `source_zone_id` bigint unsigned NOT NULL,
  `target_zone_id` bigint unsigned NOT NULL,
  `quantity` int NOT NULL,
  `source_available` int NOT NULL,
  `target_occupied` int NOT NULL,
  `target_capacity` int NOT NULL,
  `target_reserved` int NOT NULL,
  `borrow_count` int NOT NULL,
  `return_count` int NOT NULL,
  `desired_inventory` int NOT NULL,
  `window_start` datetime(3) NOT NULL,
  `window_end` datetime(3) NOT NULL,
  `reason` varchar(500) NOT NULL,
  `algorithm_version` varchar(30) NOT NULL,
  `status` enum('OPEN','CONFIRMED','STALE','DISMISSED') NOT NULL DEFAULT 'OPEN',
  `task_id` bigint unsigned DEFAULT NULL,
  `created_by` bigint unsigned NOT NULL,
  `resolution_note` varchar(500) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `resolved_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `source_zone_id` (`source_zone_id`),
  KEY `target_zone_id` (`target_zone_id`),
  KEY `task_id` (`task_id`),
  KEY `created_by` (`created_by`),
  CONSTRAINT `dispatch_suggestions_ibfk_1` FOREIGN KEY (`source_zone_id`) REFERENCES `parking_zones` (`id`),
  CONSTRAINT `dispatch_suggestions_ibfk_2` FOREIGN KEY (`target_zone_id`) REFERENCES `parking_zones` (`id`),
  CONSTRAINT `dispatch_suggestions_ibfk_3` FOREIGN KEY (`task_id`) REFERENCES `dispatch_tasks` (`id`),
  CONSTRAINT `dispatch_suggestions_ibfk_4` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `chk_suggestion_state` CHECK ((((`status` = _utf8mb4'OPEN') and (`task_id` is null) and (`resolved_at` is null)) or ((`status` = _utf8mb4'CONFIRMED') and (`task_id` is not null) and (`resolved_at` is not null)) or ((`status` in (_utf8mb4'STALE',_utf8mb4'DISMISSED')) and (`task_id` is null) and (`resolved_at` is not null)))),
  CONSTRAINT `dispatch_suggestions_chk_1` CHECK (((`quantity` > 0) and (`source_zone_id` <> `target_zone_id`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
