  `active_bike` bigint unsigned GENERATED ALWAYS AS ((case when (`status` = _utf8mb4'RUNNING') then `bike_id` end)) STORED,
  `qualification_status` enum('VALID','UNDER_REVIEW','EXCLUDED') NOT NULL DEFAULT 'VALID',
