  CONSTRAINT `ride_orders_ibfk_4` FOREIGN KEY (`end_zone_id`) REFERENCES `parking_zones` (`id`),
  CONSTRAINT `chk_ride_qualification_review` CHECK ((((`qualification_status` = _utf8mb4'UNDER_REVIEW') and (`reviewed_by` is null) and (`reviewed_at` is null)) or ((`qualification_status` = _utf8mb4'VALID') and (((`reviewed_by` is null) and (`reviewed_at` is null)) or ((`reviewed_by` is not null) and (`reviewed_at` is not null)))) or ((`qualification_status` = _utf8mb4'EXCLUDED') and (`reviewed_by` is not null) and (`reviewed_at` is not null)))),
  CONSTRAINT `chk_ride_return_pair` CHECK (((`return_x` is null) = (`return_y` is null))),
