--
-- Table structure for table `risk_alerts`
--

DROP TABLE IF EXISTS `risk_alerts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `risk_alerts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `bike_id` bigint unsigned NOT NULL,
  `score` int NOT NULL,
  `level` enum('MEDIUM','HIGH') NOT NULL,
  `reasons` json NOT NULL,
  `ticket_ids` json NOT NULL,
  `fingerprint` char(64) NOT NULL,
  `open_fingerprint` char(64) GENERATED ALWAYS AS ((case when (`status` in (_utf8mb4'OPEN',_utf8mb4'ACKNOWLEDGED')) then `fingerprint` end)) STORED,
  `rule_version` varchar(30) NOT NULL,
  `status` enum('OPEN','ACKNOWLEDGED','RESOLVED','DISMISSED') NOT NULL DEFAULT 'OPEN',
  `recommendation` varchar(300) NOT NULL,
  `handler_id` bigint unsigned DEFAULT NULL,
  `maintenance_ticket_id` bigint unsigned DEFAULT NULL,
  `resolution_note` varchar(500) DEFAULT NULL,
  `triggered_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `acknowledged_at` datetime(3) DEFAULT NULL,
  `resolved_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `open_fingerprint` (`open_fingerprint`),
  KEY `bike_id` (`bike_id`),
  KEY `handler_id` (`handler_id`),
  KEY `maintenance_ticket_id` (`maintenance_ticket_id`),
  CONSTRAINT `risk_alerts_ibfk_1` FOREIGN KEY (`bike_id`) REFERENCES `bikes` (`id`),
  CONSTRAINT `risk_alerts_ibfk_2` FOREIGN KEY (`handler_id`) REFERENCES `users` (`id`),
  CONSTRAINT `risk_alerts_ibfk_3` FOREIGN KEY (`maintenance_ticket_id`) REFERENCES `maintenance_tickets` (`id`),
  CONSTRAINT `chk_risk_state` CHECK ((((`status` = _utf8mb4'OPEN') and (`handler_id` is null) and (`acknowledged_at` is null) and (`resolved_at` is null)) or ((`status` = _utf8mb4'ACKNOWLEDGED') and (`handler_id` is not null) and (`acknowledged_at` is not null) and (`resolved_at` is null)) or ((`status` in (_utf8mb4'RESOLVED',_utf8mb4'DISMISSED')) and (`handler_id` is not null) and (`resolved_at` is not null)))),
  CONSTRAINT `risk_alerts_chk_1` CHECK ((`score` between 0 and 100))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `risk_alerts`
--

LOCK TABLES `risk_alerts` WRITE;
/*!40000 ALTER TABLE `risk_alerts` DISABLE KEYS */;
/*!40000 ALTER TABLE `risk_alerts` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `road_edges`
--

DROP TABLE IF EXISTS `road_edges`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `road_edges` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `from_node_id` bigint unsigned NOT NULL,
  `to_node_id` bigint unsigned NOT NULL,
  `distance_m` int NOT NULL,
  `safety_cost` decimal(6,2) NOT NULL DEFAULT '1.00',
  `comfort_cost` decimal(6,2) NOT NULL DEFAULT '1.00',
  `direction` enum('BOTH','FORWARD','REVERSE') NOT NULL DEFAULT 'BOTH',
  `status` enum('OPEN','CLOSED','NO_RIDE') NOT NULL DEFAULT 'OPEN',
  `slope_percent` decimal(5,2) NOT NULL DEFAULT '0.00',
  `surface` enum('SMOOTH','AVERAGE','ROUGH') NOT NULL DEFAULT 'SMOOTH',
  `shade_level` tinyint unsigned NOT NULL DEFAULT '3',
  `lighting_level` tinyint unsigned NOT NULL DEFAULT '3',
  `traffic_mix` enum('BIKE_ONLY','MIXED','MOTOR_HEAVY') NOT NULL DEFAULT 'MIXED',
  `intersection_risk` tinyint unsigned NOT NULL DEFAULT '1',
  `attribute_source` enum('SIMULATED_COURSE_DATA','MEASURED') NOT NULL DEFAULT 'SIMULATED_COURSE_DATA',
